import numpy as np,datetime,collections
def read(name):
 p=R/'results'/f'{name}.json';return json.loads(p.read_text()) if p.exists() else None
labels=json.loads((R/'manifests/evaluator-qrels.json').read_text());lines=['# MIA5150 local experiments','',f'Generated {datetime.datetime.now(datetime.timezone.utc).isoformat()}. Paid spend: **0**. Hardware: RTX2060SUPER8GB/SM75, i5-9500T, 16GB Windows RAM; Ubuntu26.04 WSL2 capped at6GB RAM/2CPU/2GB swap.','', 'This report separates released-model deployment comparisons from our own adaptation experiments. Public benchmark feedback was already exposed; none of these SkillRet results is blind final-test confirmation. Read `IMPLEMENTATION_MAP.md` for implementation boundaries.','']
def table(title,names,panel):
 lines.extend(['## '+title,'','| System | Queries | NDCG@10 | Recall@10 | Complete@10 | MRR@5 | Failed/empty |','|---|---:|---:|---:|---:|---:|---:|'])
 for name in names:
  row=read(name)
  if not row or 'rankings' not in row:continue
  target={q:panel[q] for q in row['rankings']};m=evaluate(target,row['rankings']);a=m['aggregate'];lines.append(f'| {name} | {len(target)} | {a["NDCG@10"]:.4f} | {a["Recall@10"]:.4f} | {a["Completeness@10"]:.4f} | {a["MRR@5"]:.4f} | {m["empty_rate"]:.1%} |')
 lines.append('')
table('All4392 corrected public queries: fixed6006-skill header catalog',['public-full-bm25','public-full-qwen_embed_06','public-full-skillret_embed_06','public-full-rrf'],qrels('test'))
lines+=['The dataset revision is `6583d7d2ed07644d0fb8938ed8178f3a7dc42a12`. Dense models use native query instructions, FP16, max1024tokens, exact cosine search and one query per forward pass. RRF uses k60 and the top100 from each channel. These are local bounded-context configurations, not the original8B/BF16/full-context reference.','']
table('Public128-query development screen',['bm25-locked-header','bm25-locked-full','qwen_embed_06-header-0','skillret_embed_06-header-0','rrf-skillret-bm25','skillrouter_embed_06-header-0','skillreason_embed_06-header-0','skillret_embed_06-full-0','tfidf-fields','tfidf-flattened','field-six-uniform'],labels)
lines+=['Header and full-document evidence are distinct tracks. Full neural documents and each dense field are capped at1024tokens; the report does not imply all source text was visible. Sparse full-document baselines use the available complete text. Field-six is an adaptation of uniform six-channel field cosine, not the older-pool paper leaderboard or its learned MLP. Candidate recall/completeness and rescued/displaced positives at20/50/100 are in `results/candidate-coverage.json`.','']
table('Shared32-query / identical20-candidate reranking pool',['skillret_rerank_06-header-32','skillrouter_rerank_06-header-32','skillreason_rerank_06-header-32','r3_rerank_06-header-32','jina-native'],labels)
lines+=['The pool is frozen SkillRet0.6B dense retrieval without gold insertion. Jina uses its reviewed native joint-candidate attention and learned projector, capped at8192 totaltokens, rather than a substitute pooling method. Common source headers are identical; native token layouts differ. Failed outputs retain the denominator. Native role-specific instructions are saved in source snapshots.','']
table('Bounded8-query quantized pointwise screen',['jevk5-pointwise','plumb-pointwise','qwen8-q4'],labels)
ids=list((read('jevk5-pointwise') or {}).get('rankings',{}))
if ids:
 lines.append('Matched8-query controls: '+', '.join(f'{name} NDCG@10={evaluate({q:labels[q] for q in ids},read(name)["rankings"])["aggregate"]["NDCG@10"]:.4f}' for name in ['skillret_embed_06-header-0','skillret_rerank_06-header-32','skillrouter_rerank_06-header-32','skillreason_rerank_06-header-32'] if read(name))+'.')
lines+=['','JevK5 uses Q5_K_M and native option-letter log-probabilities with T1.22; Plumb uses Q4_K_M/T2.07. Missing logits are failures, not fabricated probability floors. Qwen8 uses a pinned third-party Q4_K_M conversion and native yes/no logit differences; no BF16 parity is claimed. The capped15+NONE and21-option native multi-pass choice studies are separate from pointwise relevance and do not solve multi-skill selection. Their original/reversed order outputs are retained.','']
trainlabels=qrels('train');table('Actual rank4 q/v LoRA:32-query grouped development set',['lora-hard-base','lora-hard-adapted','lora-replay-clean-base','lora-replay-clean-adapted'],trainlabels)
lines+=['Adapters use seed5150, alpha8, lr5e-5, FP16/gradient scaling, gradient checkpointing and a384-example ceiling. All labelled positive pairs are kept; only negatives are sampled to meet the corrected replay cap. Native deployment reload and exact adapter/optimizer/scaler/RNG restoration were checked. The released base already saw public training data: these results measure new adaptation, not clean pretraining generalization.','', '**Superseded replay:** the original replay cap dropped8 of91 unique positive pairs. Its earlier0.6946 result is retained for audit but excluded from supported gains. The clean replay run is a new experiment. Older lexical files without the clean designation also include a negative-partition defect; see the exposure ledger.','']
table('LoRA transfer: same32 public queries, full512 evidence and fixed20 pools',['lora-transfer-base','lora-transfer-hard','lora-transfer-replay-clean'],labels)
lines+=['Training/test skill IDs are disjoint, but this public query panel was already inspected. This is a transfer-regression diagnostic, not untouched external confirmation. Development and transfer results must both inform any promotion.','']
table('Clean learned lexical fusion: separate128-query training-derived development set',['adaptation-clean-no-adaptation','adaptation-clean-hard-negative','adaptation-clean-label-smoothing','adaptation-anchoring'],trainlabels)
lines+=['Training uses512 queries and repository/exact-name components. Cross-partition multi-positive queries and overlapping normalized query text are excluded; development-group documents cannot enter training negatives. Label smoothing, replay and L2 anchoring are explicitly different interventions.','', '## Fixedfive-skill structural selection','', '| Method | NDCG@5 | Complete@5 | SetF1 | Exact set |','|---|---:|---:|---:|---:|']
for name in ['top5','mmr','dsr-embedding-quality','domain1','domain2-global']:
 row=read('structure-'+name)
 if row:
  a=row['metrics']['aggregate'];sets=list(row['selected_set_metrics'].values());lines.append(f'| {name} | {a["NDCG@5"]:.4f} | {a["Completeness@5"]:.4f} | {np.mean([s["f1"] for s in sets]):.4f} | {np.mean([s["exact"] for s in sets]):.4f} |')
lines+=['','No gold set size is provided to the selector. One-domain restriction loses relevant skills; global fallback recovers by retaining unrestricted hits. Similar skills may both be required, so diversity is not automatically beneficial. No compatibility, dependency or activation labels were invented.','']
row=read('escalation')
if row:lines+=['## Bounded escalation diagnostic','',f'Calibration16queries and evaluation16queries are disjoint. A label-free calibration-median margin threshold escalates {row["escalation_rate"]:.1%} of evaluation queries. NDCG@10: dense {row["baseline"]["aggregate"]["NDCG@10"]:.4f}; policy {row["metrics"]["aggregate"]["NDCG@10"]:.4f}; always rerank {row["always_strong"]["aggregate"]["NDCG@10"]:.4f}. Estimated warm latency {row["estimated_warm_latency_seconds"]}. This sum of separate component timings excludes model switching/startup and is not measured deployment end-to-end latency.','']
lines+=['## Scaling and full-catalog prompting','','The same eight queries, three seeds and random/hard-overlap nested libraries are used across10/100/1000/6006 skills. Gold-conditioned library construction is explicitly a separate experiment. No label or required-skill count enters the scorers. At10 skills, complete-list Recall@10 is trivial.','']
for name in ['scale-prompt','scale-prompt-32768']:
 row=read(name)
 if row:
  lines.append(f'{name}: context={row["context"]}; statuses='+str(dict(collections.Counter(x['status'] for x in row['raw'])))+'.')
lines+=['','Overflow and malformed outputs are counted as failures; no hidden retrieval reduces the full-catalog prompt. The32768-token track, if completed, is a separate two-query resource diagnostic. Four-query constrained-ID ranking and pairwise single-elimination are separate bounded experiments, not a full strong-LLM benchmark.','']
sra=read('sra-transfer-summary')
if sra:
 lines+=['## Frozen external SRA diagnostic','',f'{sra["queries"]} queries, four per each ofsix native task families, against all{sra["catalog"]} skills. BM25, SkillRet and equalRRF were frozen before instance-label downloads. Native Recall/nDCG calculations were checked against the reviewed official metric function. No downstream execution or tuning occurred.','']
 for name,row in sra['systems'].items():lines.append(f'- {name}: {row["native_metrics"]}')
 lines+=['','Checkpoint exposure cannot be proven absent, so this is external transfer, not certified blind confirmation. Native task-family scores remain separate in the raw summary.','']
stats=read('paired-statistics') or {};lines+=['## Paired uncertainty and promotion','','Gold-overlap connected-component bootstrap,2000 resamples, seed5150. The following intervals are exploratory and not corrected for the multiple screened methods. A positive development mean alone is insufficient for promotion.','', '| Contrast | NDCG@10 delta | Cluster95% interval | Wins/losses/ties |','|---|---:|---|---|']
for name,row in stats.items():
 a=row['contrasts']['NDCG@10'];lines.append(f'| {name} | {a["delta"]:+.4f} | [{a["cluster_bootstrap_ci95"][0]:+.4f}, {a["cluster_bootstrap_ci95"][1]:+.4f}] | {a["wins"]}/{a["losses"]}/{a["ties"]} |')
lines+=['','Deployment shortlist: retain SkillRet0.6B as the reference, equalRRF as the inexpensive candidate, and the best measured0.6B reranker as a quality candidate pending broader paired validation. Do not promote a LoRA, domain restriction, diversity policy or escalation rule solely on these small development means. The two leading released rerankers should not be ordered confidently by a sub-0.001 difference.','', '## Resource and reproducibility limits','', 'All expensive stages ran sequentially through `guard.py`. Successful runs must show no new swap activity and the requested reserves. Failed loading attempts are retained and excluded from completed-run claims. Direct-to-GPU loading and completed-file cache hints reduced transient pressure without changing WSL limits. `results/resources.json` reports measured maxima/minima; raw telemetry is retained. WorkerCPU/RSS excludes child llama servers; whole-guest CPU ticks and whole-device GPU measurements remain available. Warm timings, indexing and startup are separate; these are deployment configurations rather than a precision-controlled hardware speed contest.','', 'The8B BF16 reference, hosted/API models, RunPod, extensive multiseed training, certified independent confirmation, and full-query neural reranking tournament were not represented by these bounded pilots. The runnable reranker accepts a4392-query limit and full-public candidate artifact for a future longer run. Full32K dense-body reproduction, SkillReason4B training and labelled activation/compatibility/graph studies remain outside the completed comparisons.','', 'SRA and SkillReason are distinct external benchmarks. SRA was prioritized; a separate SkillReason-Bench native-protocol/exposure audit and evaluation is not claimed. Additional conditional retrieval encoders should be justified by the saved miss-coverage evidence, not added to an opaque combined score.','', 'Historical Jev200/6006 results, the historical LoRA10123/256val study and the custom80-case routing pilot are retained as separate context. No new result was merged into their metrics. No paid service, credential extraction, publication, model upload or Git push occurred.','', '## Receipts','', 'See `evidence/tests.json`, `evidence/notebook-smoke.json`, `evidence/plan-integrity.json`, `evidence/exposure-ledger.json`, `requirements-lock.txt`, exact `runs/*/command.json` and source snapshots. `PACKAGE_SHA256.json` covers the portable deliverables. The package excludes bulk data, base weights, environments, caches, credentials and Git internals.','']
external=read('skillreason-transfer')
if external:
 lines=[s.replace('SRA was prioritized; a separate SkillReason-Bench native-protocol/exposure audit and evaluation is not claimed.','Both external adapters were evaluated as separate diagnostics; neither has certified checkpoint-exposure independence.') for s in lines]
 lines+=['## SkillReason-Bench external diagnostic','','Frozen first24 hashed query IDs, full61228-skill header pool, FP16/max1024, documentbatch4/querybatch1. Research-use terms were read; source skill metadata retained locally and raw source corpus excluded from the package. Single-positive native metrics are not averaged with SRA or SkillRet.','']
